package sim

import (
	"compress/gzip"
	"encoding/gob"
	"fmt"
	"io"
)

// saveVersion is bumped whenever the saved format changes incompatibly.
const saveVersion = 3

// savedPlanet is everything needed to restore a planet. Things derived from
// the seed and size (terrain neighbours, latitudes, CO₂ per ice) are
// regenerated by NewPlanet rather than saved.
type savedPlanet struct {
	Version   int
	N         int
	Seed      uint64
	Tiles     []Tile
	Air       Air
	Vapour    float64
	Impacts   int
	Ticks     uint64
	GoalsDone int
	Buildings []savedBuilding
	Stores    Amounts
	Produced  Amounts
	// Added later; older saves decode them as empty.
	Orbitals   []orbital
	TrialStart uint64
	Level      int
	Built      int
	WonAt      uint64
	LiftedOff  bool
	Soletta    float64
}

type savedBuilding struct {
	Type    BuildingType
	Tile    int
	In, Out Amounts
	Timer   int
}

// Save writes the planet to w, gzip-compressed.
func (p *Planet) Save(w io.Writer) error {
	s := savedPlanet{
		Version:    saveVersion,
		N:          p.Grid.N,
		Seed:       p.Seed,
		Tiles:      p.Tiles,
		Air:        p.Air,
		Vapour:     p.Vapour,
		Impacts:    p.impacts,
		Ticks:      p.Ticks,
		GoalsDone:  p.goalsDone,
		Stores:     p.eco.Stores,
		Produced:   p.eco.Produced,
		Orbitals:   p.orbitals,
		TrialStart: p.trialStart,
		Level:      p.Level,
		Built:      p.built,
		WonAt:      p.wonAt,
		LiftedOff:  p.liftedOff,
		Soletta:    p.solettaPower,
	}
	for _, b := range p.eco.buildings {
		s.Buildings = append(s.Buildings, savedBuilding{Type: b.Type, Tile: b.Tile, In: b.In, Out: b.Out, Timer: b.Timer})
	}
	zw := gzip.NewWriter(w)
	if err := gob.NewEncoder(zw).Encode(&s); err != nil {
		return err
	}
	return zw.Close()
}

// Load reads a planet written by Save.
func Load(r io.Reader) (*Planet, error) {
	zr, err := gzip.NewReader(r)
	if err != nil {
		return nil, err
	}
	var s savedPlanet
	if err := gob.NewDecoder(zr).Decode(&s); err != nil {
		return nil, err
	}
	if s.Version != saveVersion {
		return nil, fmt.Errorf("save is from a different version of the game (format %d, want %d)", s.Version, saveVersion)
	}
	if s.N <= 0 || len(s.Tiles) != (Grid{N: s.N}).NumCells() {
		return nil, fmt.Errorf("save has %d tiles for size %d", len(s.Tiles), s.N)
	}
	p := NewPlanetLevel(s.N, s.Seed, s.Level)
	copy(p.Tiles, s.Tiles)
	p.Air, p.Vapour, p.impacts = s.Air, s.Vapour, s.Impacts
	p.updateClimate()
	p.Ticks = s.Ticks
	p.goalsDone = s.GoalsDone
	p.eco.Stores = s.Stores
	p.eco.Produced = s.Produced
	for _, sb := range s.Buildings {
		if sb.Tile < 0 || sb.Tile >= len(p.Tiles) || sb.Type < 0 || sb.Type >= NumBuildingTypes || p.eco.at[sb.Tile] != nil {
			return nil, fmt.Errorf("save has an invalid building: %+v", sb)
		}
		b := p.place(sb.Type, sb.Tile)
		b.In, b.Out, b.Timer = sb.In, sb.Out, sb.Timer
	}
	for _, o := range s.Orbitals {
		if o.Type < 0 || o.Type >= NumBuildingTypes || !Specs[o.Type].Orbital {
			return nil, fmt.Errorf("save has an invalid orbital project: %+v", o)
		}
	}
	p.orbitals, p.trialStart = s.Orbitals, s.TrialStart
	p.built, p.wonAt, p.liftedOff, p.solettaPower = s.Built, s.WonAt, s.LiftedOff, s.Soletta
	return p, nil
}
